#include <whb/proc.h>
#include <coreinit/screen.h>
#include <coreinit/memdefaultheap.h>
#include <vpad/input.h>
#include <mocha/mocha.h>
#include <cstdio>
#include <string>
#include <vector>
#include "TitleScanner.hpp"
#include "JsonExporter.hpp"
namespace{void*tv=nullptr;void*drc=nullptr;void Init(){OSScreenInit();tv=MEMAllocFromDefaultHeapEx(OSScreenGetBufferSizeEx(SCREEN_TV),0x100);drc=MEMAllocFromDefaultHeapEx(OSScreenGetBufferSizeEx(SCREEN_DRC),0x100);OSScreenSetBufferEx(SCREEN_TV,tv);OSScreenSetBufferEx(SCREEN_DRC,drc);OSScreenEnableEx(SCREEN_TV,true);OSScreenEnableEx(SCREEN_DRC,true);}void Draw(const std::vector<std::string>&l){for(int x=SCREEN_TV;x<=SCREEN_DRC;++x){auto s=static_cast<OSScreenID>(x);OSScreenClearBufferEx(s,0x101820FF);uint32_t y=2;for(auto&a:l)OSScreenPutFontEx(s,2,y++,a.c_str());OSScreenFlipBuffersEx(s);}}void EndScreen(){OSScreenEnableEx(SCREEN_TV,false);OSScreenEnableEx(SCREEN_DRC,false);if(tv)MEMFreeToDefaultHeap(tv);if(drc)MEMFreeToDefaultHeap(drc);}}
int main(int,char**){WHBProcInit();VPADInit();Init();Draw({"GameVault Wii U Exporter v0.1.0-dev2","","Initializing Mocha..."});if(Mocha_InitLibrary()==MOCHA_RESULT_SUCCESS){const bool usb=Mocha_MountFS("storage_usb01",nullptr,"/vol/storage_usb01")==MOCHA_RESULT_SUCCESS;const bool mlc=Mocha_MountFS("storage_mlc01",nullptr,"/vol/storage_mlc01")==MOCHA_RESULT_SUCCESS;Draw({"GameVault Wii U Exporter v0.1.0-dev2","","Scanning installed titles..."});std::vector<InstalledTitle>t;std::string e;if(!ScanInstalledTitles(t,e))Draw({"GameVault Wii U Exporter","","SCAN FAILED",e,"","Press A or HOME to exit"});else if(!ExportJson(t,e))Draw({"GameVault Wii U Exporter","","EXPORT FAILED",e,"","Press A or HOME to exit"});else{unsigned g=0,u=0,d=0;for(auto&x:t){if(x.kind=="GAME")++g;else if(x.kind=="UPDATE")++u;else if(x.kind=="DLC")++d;}char a[64],b[96];snprintf(a,sizeof(a),"Export successful: %u titles",(unsigned)t.size());snprintf(b,sizeof(b),"Games: %u   Updates: %u   DLC: %u",g,u,d);Draw({"GameVault Wii U Exporter v0.1.0-dev2","",a,b,"","installed_titles.json written to SD","Press A or HOME to exit"});}while(WHBProcIsRunning()){VPADStatus s{};VPADReadError r{};if(VPADRead(VPAD_CHAN_0,&s,1,&r)>0&&(s.trigger&VPAD_BUTTON_A))break;}Draw({"GameVault Wii U Exporter v0.1.0-dev2","","Returning to Aroma..."});(void)usb;(void)mlc;Mocha_DeInitLibrary();}else Draw({"GameVault Wii U Exporter","","ERROR: Mocha_InitLibrary failed"});EndScreen();VPADShutdown();WHBProcShutdown();return 0;}
